using System.Security.Claims;
using Core.Authorization;
using Core.Modules;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
using Microsoft.Extensions.DependencyInjection;
using Modules.Purchasing.DTOs;
using Modules.Purchasing.Entities;
using Modules.Purchasing.Repositories;
using Modules.Purchasing.Services;
using Shared.Primitives.Identifiers;

namespace Modules.Purchasing;

public static class PurchasingModuleExtensions
{
    public static IServiceCollection AddPurchasingModule(this IServiceCollection services)
    {
        services.AddSingleton<IModuleManifestProvider, PurchasingModuleManifestProvider>();
        services.AddSingleton<Repositories.PurchasingRepository>();
        services.AddSingleton<Repositories.PurchasingOwnerReconciliationSource>();
        services.AddSingleton<Shared.Contracts.Planning.IPlanningOwnerReconciliationSource>(p => p.GetRequiredService<Repositories.PurchasingOwnerReconciliationSource>());
        services.AddSingleton<PurchasingService>();
        services.AddSingleton<Shared.Contracts.Purchasing.IPurchasingSourceCapabilities>(p => p.GetRequiredService<PurchasingService>());
        services.AddSingleton<Shared.Contracts.Purchasing.IPurchasingFixedAssetCapabilities>(p => p.GetRequiredService<PurchasingService>());
        services.AddSingleton<Shared.Contracts.Purchasing.IPurchasingReadCapabilities>(p => p.GetRequiredService<PurchasingService>());
        services.AddSingleton<Shared.Contracts.Purchasing.IManufacturingSubcontractSourceCapabilities>(p => p.GetRequiredService<PurchasingService>());
        services.AddSingleton<Shared.Contracts.Purchasing.IPurchasingLandedCostCapabilities>(p => p.GetRequiredService<PurchasingService>());
        services.AddSingleton<Shared.Contracts.Quality.IPurchasingQualityDispositionCapabilities, Services.PurchasingQualityDispositionOwner>();
        services.AddSingleton<Shared.Contracts.ManufacturingPlanning.IManufacturingSupplyCapabilities>(p => p.GetRequiredService<PurchasingService>());
        return services;
    }

    public static WebApplication MapPurchasingModule(this WebApplication app)
    {
        var group = app.MapGroup("/api/v1/purchasing").WithTags("Purchasing").RequireAuthorization().RequireRateLimiting("api").AddModuleLifecycleEnforcement();
        group.MapGet("/legal-entities/{entityId:guid}/purchase-orders", async (Guid entityId, string? state, string? search, int? page, int? pageSize, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) =>
            await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.po.read", entityId, ct), () => service.ListAsync(Tenant(http), entityId, state, search, page ?? 1, pageSize ?? 50, ct))).RequireModuleRead("purchasing");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-requisitions", async (Guid entityId, CreatePurchaseRequisitionRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) =>
        {
            if (request.LegalEntityId != entityId) return Results.BadRequest(new { code = "purchasing.entity_mismatch" });
            return await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.request.create", entityId, ct), () => service.CreateRequisitionAsync(Tenant(http), Actor(http), request, ct), StatusCodes.Status201Created);
        }).RequireModuleMutation("purchasing", "purchasing.request.create");
        group.MapGet("/legal-entities/{entityId:guid}/purchase-requisitions/{id:guid}", async (Guid entityId, Guid id, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.request.read", entityId, ct), () => service.GetRequisitionAsync(Tenant(http), entityId, id, ct))).RequireModuleRead("purchasing");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-requisitions/{id:guid}/submit", async (Guid entityId, Guid id, PurchaseRequisitionCommandRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.request.create", entityId, ct), () => service.SubmitRequisitionAsync(Tenant(http), Actor(http), Membership(http), entityId, id, request, ct))).RequireModuleMutation("purchasing", "purchasing.request.create");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-requisitions/{id:guid}/approve", async (Guid entityId, Guid id, PurchaseRequisitionCommandRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.request.approve", entityId, ct), () => service.DecideRequisitionAsync(Tenant(http), Actor(http), Membership(http), entityId, id, request, "Approved", ct))).RequireModuleMutation("purchasing", "purchasing.request.approve");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-requisitions/{id:guid}/reject", async (Guid entityId, Guid id, PurchaseRequisitionCommandRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.request.approve", entityId, ct), () => service.DecideRequisitionAsync(Tenant(http), Actor(http), Membership(http), entityId, id, request, "Rejected", ct))).RequireModuleMutation("purchasing", "purchasing.request.approve");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-requisitions/{id:guid}/convert", async (Guid entityId, Guid id, ConvertPurchaseRequisitionRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.po.create", entityId, ct), () => service.ConvertRequisitionAsync(Tenant(http), Actor(http), entityId, id, request, ct), StatusCodes.Status201Created)).RequireModuleMutation("purchasing", "purchasing.po.create");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders", async (Guid entityId, CreatePurchaseOrderRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) =>
        {
            if (request.LegalEntityId != entityId) return Results.BadRequest(new { code = "purchasing.entity_mismatch" });
            var access = await AccessAsync(http, subjects, authorizer, "purchasing.po.create", entityId, ct);
            if (access is { Allowed: true } && request.Lines.Any(x => x.UnitPrice is not null) && !await HasPermissionAsync(http, subjects, authorizer, "purchasing.price.override", entityId, ct)) return Results.Forbid();
            var canOverride = access?.Allowed == true && await HasPriceOverride(http, subjects, authorizer, entityId, ct);
            return await Execute(http, access, () => service.CreateAsync(Tenant(http), Actor(http), request, canOverride, Correlation(http), ct), StatusCodes.Status201Created);
        }).RequireModuleMutation("purchasing", "purchasing.po.create");
        group.MapGet("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}", async (Guid entityId, Guid id, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => { var access = await AccessAsync(http, subjects, authorizer, "purchasing.po.read", entityId, ct); var includePrice = await HasPermissionAsync(http, subjects, authorizer, "purchasing.price.read", entityId, ct); return await Execute(http, access, () => service.GetAsync(Tenant(http), entityId, id, includePrice, ct)); }).RequireModuleRead("purchasing");
        group.MapPut("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}", async (Guid entityId, Guid id, UpdatePurchaseOrderRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) =>
        {
            var access = await AccessAsync(http, subjects, authorizer, "purchasing.po.edit", entityId, ct);
            if (access is { Allowed: true } && request.Lines.Any(x => x.UnitPrice is not null) && !await HasPermissionAsync(http, subjects, authorizer, "purchasing.price.override", entityId, ct)) return Results.Forbid();
            return await Execute(http, access, () => service.UpdateAsync(Tenant(http), Actor(http), entityId, id, request, false, Correlation(http), ct));
        }).RequireModuleMutation("purchasing", "purchasing.po.edit");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/amend", async (Guid entityId, Guid id, UpdatePurchaseOrderRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) =>
            await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.po.amend", entityId, ct), () => service.UpdateAsync(Tenant(http), Actor(http), entityId, id, request, true, Correlation(http), ct, true, "Controlled amendment"))).RequireModuleMutation("purchasing", "purchasing.po.amend");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/approve", async (Guid entityId, Guid id, PurchaseOrderCommandRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.po.approve", entityId, ct), () => service.ApproveAsync(Tenant(http), Actor(http), entityId, id, request, Correlation(http), ct))).RequireModuleMutation("purchasing", "purchasing.po.approve");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/reject", async (Guid entityId, Guid id, PurchaseOrderCommandRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.po.reject", entityId, ct), () => service.RejectAsync(Tenant(http), Actor(http), entityId, id, request, Correlation(http), ct))).RequireModuleMutation("purchasing", "purchasing.po.reject");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/cancel-remaining", async (Guid entityId, Guid id, PurchaseOrderCommandRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.po.cancel", entityId, ct), () => service.CancelAsync(Tenant(http), Actor(http), entityId, id, request, Correlation(http), ct))).RequireModuleMutation("purchasing", "purchasing.po.cancel");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/close", async (Guid entityId, Guid id, PurchaseOrderCommandRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.po.close", entityId, ct), () => service.CloseAsync(Tenant(http), Actor(http), entityId, id, request, Correlation(http), ct))).RequireModuleMutation("purchasing", "purchasing.po.close");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/close-short", async (Guid entityId, Guid id, PurchaseOrderCommandRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.po.close", entityId, ct), () => service.CloseShortAsync(Tenant(http), Actor(http), entityId, id, request, Correlation(http), ct))).RequireModuleMutation("purchasing", "purchasing.po.close");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/receive", async (Guid entityId, Guid id, ReceivePurchaseOrderRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.receipt.request", entityId, ct), () => service.ReceiveAsync(Tenant(http), Actor(http), entityId, id, request, Correlation(http), ct), StatusCodes.Status201Created)).RequireModuleMutation("purchasing", "purchasing.receipt.request");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/create-supplier-invoice", async (Guid entityId, Guid id, CreateSupplierInvoiceRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.invoice.create_from_po", entityId, ct), () => service.CreateSupplierInvoiceAsync(Tenant(http), Actor(http), Membership(http), entityId, id, request, Correlation(http), ct), StatusCodes.Status201Created)).RequireModuleMutation("purchasing", "purchasing.invoice.create_from_po");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/approve-and-bill", async (Guid entityId, Guid id, ApproveAndBillRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.po.approve", entityId, ct), () => service.ApproveAndBillAsync(Tenant(http), Actor(http), Membership(http), entityId, id, request.Approval, request.Invoice, Correlation(http), ct), StatusCodes.Status201Created)).RequireModuleMutation("purchasing", "purchasing.po.approve");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/receive-and-bill", async (Guid entityId, Guid id, ReceiveAndBillRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.receipt.request", entityId, ct), () => service.ReceiveAndBillAsync(Tenant(http), Actor(http), Membership(http), entityId, id, request.Receipt, request.Invoice, Correlation(http), ct), StatusCodes.Status201Created)).RequireModuleMutation("purchasing", "purchasing.receipt.request");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/match", async (Guid entityId, Guid id, MatchPurchaseOrderRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, request.ApproveException ? "purchasing.match.override" : "purchasing.match.read", entityId, ct), () => service.MatchAsync(Tenant(http), Actor(http), entityId, id, request, Correlation(http), ct))).RequireModuleMutation("purchasing", "purchasing.match.override");
        group.MapGet("/legal-entities/{entityId:guid}/suppliers/{supplierId:guid}/profile", async (Guid entityId, Guid supplierId, HttpContext http, PurchasingRepository repository, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.po.read", entityId, ct), () => repository.GetProfileAsync(Tenant(http), entityId, supplierId, ct))).RequireModuleRead("purchasing");
        group.MapPut("/legal-entities/{entityId:guid}/suppliers/{supplierId:guid}/profile", async (Guid entityId, Guid supplierId, SupplierPurchaseProfileRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.supplier_profile.manage", entityId, ct), () => service.SaveProfileAsync(Tenant(http), Actor(http), request with { LegalEntityId = entityId, SupplierPartyId = supplierId }, ct))).RequireModuleMutation("purchasing", "purchasing.supplier_profile.manage");
        group.MapGet("/legal-entities/{entityId:guid}/settings", async (Guid entityId, HttpContext http, PurchasingRepository repository, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.settings.manage", entityId, ct), () => repository.GetSettingsAsync(Tenant(http), entityId, ct))).RequireModuleRead("purchasing");
        group.MapPut("/legal-entities/{entityId:guid}/settings", async (Guid entityId, PurchaseSettingsRequest request, HttpContext http, PurchasingRepository repository, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.settings.manage", entityId, ct), () => repository.SaveSettingsAsync(Tenant(http), Actor(http), request with { LegalEntityId = entityId }, ct))).RequireModuleMutation("purchasing", "purchasing.settings.manage");
        group.MapPost("/legal-entities/{entityId:guid}/purchase-orders/{id:guid}/returns", async (Guid entityId, Guid id, CreateSupplierReturnRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.return.create", entityId, ct), () => service.CreateReturnAsync(Tenant(http), Actor(http), entityId, id, request, ct), StatusCodes.Status201Created)).RequireModuleMutation("purchasing", "purchasing.return.create");
        group.MapGet("/legal-entities/{entityId:guid}/returns/{id:guid}", async (Guid entityId, Guid id, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.history.read", entityId, ct), () => service.GetReturnAsync(Tenant(http), entityId, id, ct))).RequireModuleRead("purchasing");
        group.MapPost("/legal-entities/{entityId:guid}/returns/{id:guid}/approve", async (Guid entityId, Guid id, PurchaseOrderCommandRequest request, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.return.approve", entityId, ct), () => service.ApproveReturnAsync(Tenant(http), Actor(http), entityId, id, request.Version, ct))).RequireModuleMutation("purchasing", "purchasing.return.approve");
        group.MapPost("/legal-entities/{entityId:guid}/returns/{id:guid}/execute", async (Guid entityId, Guid id, HttpContext http, PurchasingService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "purchasing.return.execute", entityId, ct), () => service.ExecuteReturnAsync(Tenant(http), Actor(http), Membership(http), entityId, id, ct))).RequireModuleMutation("purchasing", "purchasing.return.execute");
        return app;
    }

    private static async Task<IResult> Execute<T>(HttpContext http, Access? access, Func<Task<T>> action, int status = StatusCodes.Status200OK)
    { if (access is null) return Results.Unauthorized(); if (!access.Allowed) return Results.Forbid(); try { var result = await action(); return status == StatusCodes.Status201Created ? Results.Created(http.Request.Path, result) : Results.Ok(result); } catch (PurchasingException ex) { var statusCode = ex.Code.Contains("not_found", StringComparison.Ordinal) ? 404 : ex.Code.Contains("stale", StringComparison.Ordinal) || ex.Code.Contains("conflict", StringComparison.Ordinal) || ex.Code.Contains("already", StringComparison.Ordinal) ? 409 : 400; return Results.Problem(statusCode: statusCode, title: ex.Message, extensions: new Dictionary<string, object?> { ["code"] = ex.Code }); } catch (Core.Transactions.PlanningBudgetControlException ex) { var statusCode = ex.Code.Contains("insufficient", StringComparison.Ordinal) ? 409 : 400; return Results.Problem(statusCode: statusCode, title: ex.Message, extensions: new Dictionary<string, object?> { ["code"] = ex.Code }); } }
    private static async Task<Access?> AccessAsync(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, Guid entity, CancellationToken ct)
    { if (!Guid.TryParse(http.User.FindFirstValue("tenant_id"), out var tenant) || !Guid.TryParse(http.User.FindFirstValue("membership_id"), out var membership) || !Guid.TryParse(http.User.FindFirstValue(ClaimTypes.NameIdentifier), out var actor)) return null; var subject = await subjects.LoadAsync(new TenantId(tenant), membership, ct); return subject is null ? null : new(new TenantId(tenant), actor, membership, authorizer.Authorize(subject, permission, PermissionScope.ForLegalEntity(new TenantId(tenant), new LegalEntityId(entity)))); }
    private static async Task<bool> HasPermissionAsync(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, Guid entity, CancellationToken ct) => (await AccessAsync(http, subjects, authorizer, permission, entity, ct))?.Allowed == true;
    private static Task<bool> HasPriceOverride(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, Guid entity, CancellationToken ct) => HasPermissionAsync(http, subjects, authorizer, "purchasing.price.override", entity, ct);
    private static TenantId Tenant(HttpContext http) => new(Guid.Parse(http.User.FindFirstValue("tenant_id")!));
    private static Guid Actor(HttpContext http) => Guid.Parse(http.User.FindFirstValue(ClaimTypes.NameIdentifier)!);
    private static Guid Membership(HttpContext http) => Guid.Parse(http.User.FindFirstValue("membership_id")!);
    private static Guid Correlation(HttpContext http) => Guid.TryParse(http.Request.Headers["X-Correlation-ID"], out var value) ? value : Guid.CreateVersion7();
    private sealed record Access(TenantId Tenant, Guid ActorId, Guid MembershipId, bool Allowed);
    private sealed record ApproveAndBillRequest(PurchaseOrderCommandRequest Approval, CreateSupplierInvoiceRequest Invoice);
    private sealed record ReceiveAndBillRequest(ReceivePurchaseOrderRequest Receipt, CreateSupplierInvoiceRequest Invoice);
}

