), new(["PurchaseOrderApprovedV1", "PurchaseOrderAmendedV1", "PurchaseOrderCancelledV1", "PurchaseOrderClosedV1", "PurchaseInvoiceRequestedV1", "PurchaseInvoiceLinkedV1", "PurchaseOrderReceiptLinkedV1", "PurchaseMatchEvaluatedV1", "SupplierReturnRequestedV1", "SupplierReturnCompletedV1"], []), new(false, "blocked_if_dependents"));
